import unittest

from tags import normalize_tag, tags_for_display


class TagTests(unittest.TestCase):
    def test_formats_tags_for_display(self):
        self.assertEqual(tags_for_display(["news", "local"]), "news, local")

    def test_normalizes_tag(self):
        self.assertEqual(normalize_tag("  Field   Service "), "field-service")
        self.assertEqual(normalize_tag("   "), "")


if __name__ == "__main__":
    unittest.main()

