import unittest

from formatter import format_name


class FormatNameTests(unittest.TestCase):
    def test_formats_name(self):
        self.assertEqual(format_name("Ada", "Lovelace"), "Ada Lovelace")

    def test_rejects_non_string_parts(self):
        with self.assertRaises(TypeError):
            format_name("Ada", None)


if __name__ == "__main__":
    unittest.main()

